import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, Texture } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [
    { text: 'Pricing 3', role: 'headline', typography: { fontSize: 39 } },
  ];

  // outer group — adapter applies scenePosition/rotation/scale to this.
  const group = new Group();
  group.name = 'pricing-card-3-label';

  // inner group — carries all local motion so it never fights the adapter's transform.
  const inner = new Group();
  group.add(inner);

  // ---- card plaque: engineered gradient surface (ink -> surface) ----
  const cardW = 1.3;
  const cardH = 0.42;
  const cardD = 0.06;
  const cardGeo = new BoxGeometry(cardW, cardH, cardD, 1, 1, 1);

  const grainTex = new Texture();
  grainTex.colorSpace = THREE.SRGBColorSpace;

  const inkColor = color(colors.ink);
  const surfaceColor = color(colors.surface);
  const uvNode = uv();
  const gradientNode = mix(surfaceColor, inkColor, uvNode.y);
  const grainNode = texture(grainTex);
  const grainAmount = uniform(0.0); // ramps to 0.08 once the isolated asset loads (subtle grain only)
  const finalColorNode = mix(gradientNode, grainNode, grainAmount);

  const cardMat = new MeshStandardNodeMaterial();
  cardMat.colorNode = finalColorNode;
  cardMat.roughness = 0.58;
  cardMat.metalness = 0.4;
  cardMat.clearcoat = 0.2;
  cardMat.clearcoatRoughness = 0.4;

  const cardMesh = new Mesh(cardGeo, cardMat);
  inner.add(cardMesh);

  let grainLoaded = false;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        grainTex.image = tex.image;
        grainTex.wrapS = tex.wrapS;
        grainTex.wrapT = tex.wrapT;
        grainTex.needsUpdate = true;
        grainLoaded = true;
        grainAmount.value = 0.08;
      })
      .catch(() => {});
  }

  // ---- accent trim underline (signal red, the single accent, kept small) ----
  const trimGeo = new BoxGeometry(cardW * 0.86, 0.02, cardD + 0.01);
  const trimMat = new MeshStandardNodeMaterial();
  trimMat.colorNode = color(colors.accent);
  trimMat.emissiveNode = color(colors.accent).mul(1.1);
  trimMat.roughness = 0.4;
  trimMat.metalness = 0.3;
  const trimMesh = new Mesh(trimGeo, trimMat);
  trimMesh.position.set(0, -cardH * 0.5 + 0.045, cardD * 0.5 + 0.005);
  inner.add(trimMesh);

  // ---- headline label text (verbatim from spec) ----
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const textStr = headlineItem?.text ?? 'Pricing 3';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const textMesh = ctx.fontAtlas.createText(textStr, {
    fontSize,
    color: colors.paper,
    align: 'center',
  });
  textMesh.position.set(0, 0.02, cardD * 0.5 + 0.012);
  inner.add(textMesh);

  // ---- motion: weighted-settle entrance + one slow idle breathing transform ----
  inner.scale.setScalar(0.001);

  const tl = gsap.timeline();
  tl.to(inner.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(inner.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.6 });
  idleTl.to(inner.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 2.6,
    ease: 'sine.inOut',
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    idleTl.kill();
    cardGeo.dispose();
    cardMat.dispose();
    trimGeo.dispose();
    trimMat.dispose();
    grainTex.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) {
      if (Array.isArray(textMesh.material)) {
        textMesh.material.forEach((m) => m.dispose?.());
      } else {
        textMesh.material.dispose?.();
      }
    }
  };

  return group;
}
